import { Icon, type IconName } from '../Icon/Icon';
import styles from './Button.module.css';

export type ButtonVariant = 'primary' | 'secondary' | 'tertiary';
export type ButtonState = 'default' | 'hover' | 'active' | 'focus';

type CommonProps = {
  /** Figma \`variant\`. */
  variant?: ButtonVariant;
  /** Button label (Figma \`Text\` property). */
  children: ReactNode;
  /** Icon before the label (Figma \`Show left icon\` + \`Swap icon\`). */
  iconLeft?: IconName;
  /** Icon after the label (Figma \`Show right icon\` + \`Swap icon\`). */
  iconRight?: IconName;
  /**
   * Forces a visual state for static mockups and docs.
   * Leave unset in real use – hover, active and focus come from the browser.
   */
  state?: ButtonState;
};

type AsButton = CommonProps & ButtonHTMLAttributes<HTMLButtonElement> & { href?: undefined };
type AsLink = CommonProps & AnchorHTMLAttributes<HTMLAnchorElement> & { href: string };
export type ButtonProps = AsButton | AsLink;

/** Primary, secondary and tertiary buttons. Renders an \`<a>\` when given \`href\`. */
export function Button(props: ButtonProps) {
  const { variant = 'primary', children, iconLeft, iconRight, state, className, ...rest } = props;
  const classes = [styles.button, styles[variant], className].filter(Boolean).join(' ');
  const content = (
    <>
      {iconLeft && <Icon name={iconLeft} size={20} className={styles.icon} />}
      <span className={styles.label}>{children}</span>
      {iconRight && <Icon name={iconRight} size={20} className={styles.icon} />}
    </>
  );
  const dataState = state && state !== 'default' ? state : undefined;

  if (rest.href !== undefined) {
    return (
      <a className={classes} data-state={dataState} {...(rest as AnchorHTMLAttributes<HTMLAnchorElement>)}>
        {content}
      </a>
    );
  }
  return (
    <button
      type="button"
      className={classes}
      data-state={dataState}
      {...(rest as ButtonHTMLAttributes<HTMLButtonElement>)}
    >
      {content}
    </button>
  );
}
